---更新色彩数据
---@param jsonData table
function PlayerDojo:Fill(jsonData)
    jsonData = checkTable(jsonData)
    for key, value in pairs(jsonData) do
        --只更新自己关心的数据
        if isSet(jsonData, key) and table.haskey(self, key) then
            if key == "playerId" then
                self:PlayerId(checkString(value))
            else
                self[key] = checkString(value)
            end
        end
    end
    if isSet(jsonData, "serverTime") then
        self.clientTime = os.time()
    end
    if isSet(jsonData, "level") then
        xRecord.setUserPlayer({ playerLevel = tostring(jsonData.level) })
    end
    if isSet(jsonData, "loginDayNum") then
        self.loginDayNum = checkInt(jsonData.loginDayNum) 
    end
    if isSet(jsonData, "currency") then
        self.currency = {}
        for id, v in pairs(checkTable(jsonData.currency)) do
            self.currency[tostring(id)] = checkNumber(v)
        end
    else
        self.currency = {}
    end
    if isSet(jsonData, "revealTeam") then
        self.revealTeam = {}
        for k, v in pairs(jsonData.revealTeam) do
            if v ~= '' then
                self.revealTeam[checkInt(k)] = v
            end
        end
    else
        self.revealTeam = {}
    end
    if isSet(jsonData, "playerOtherInfo") then
        self.playerOtherInfo = {}
        for k, v in pairs(jsonData.playerOtherInfo) do
            if v then
                self.playerOtherInfo[checkString(k)] = checkTable(v)
            end
        end
    else
        self.playerOtherInfo = {}
    end

    if isSet(jsonData, "medals") then
        self.medals = {}
        for k, v in pairs(jsonData.medals) do
            if v then
                self.medals[checkString(k)] = checkTable(v)
            end
        end
    else
        self.medals = {}
    end

    if isSet(jsonData, "texture") then
        self.texture = table.deserialize(jsonData.texture)
        if isNull(self.texture) then
            self.texture = {}
        end
    else
        self.texture = {}
    end
    if isSet(jsonData, "partyCatInfo") then
        local t = checkTable(jsonData.partyCatInfo)
        if t and isSet(t, 'genes') then
            local genes = {}
            for i, v in pairs(t.genes) do
                table.insert(genes, checkNumber(v.geneId))
            end
            self.partyCatInfo = {
                playerCatId = checkNumber(t.playerCatId),
                catId = checkNumber(t.catId),
                genes = genes
            }
        end
    end
    --- 原先的 signboardCardId 用于存储
    if isSet(jsonData, "signboardCardId") then
        self.signboardId = checkNumber(jsonData.signboardCardId)
    end

    --- 孵化月卡数据
    if isSet(jsonData, "privilegeCards") then
        self.privilegeCards = jsonData.privilegeCards
    end

    --- 特权卡
    if isSet(jsonData, "overseaPrivilegeCard") then
        self.overseaPrivilegeCard = jsonData.overseaPrivilegeCard
    end
    if isSet(jsonData, "drawnRookie2Gift") then
        self.drawnRookie2Gift = jsonData.drawnRookie2Gift
    end
    if isSet(jsonData, "channelProductIds") then
        self.channelProductIds = jsonData.channelProductIds
    end

    if isSet(jsonData, "newbieGuideTaskReceived") then
        local newbieGuideTaskReceived = jsonData.newbieGuideTaskReceived
        local t = string.isEmpty(newbieGuideTaskReceived) and {} or parse_strings(newbieGuideTaskReceived, ",")
        self.newbieGuideTaskReceived = t
    else
        self.newbieGuideTaskReceived = {}
    end
    if isSet(jsonData, "firstPay") then
        self.firstPay = checkNumber(jsonData.firstPay)
    end

    if isSet(jsonData, "overseaFirstGift") then
        self.overseaFirstGift = jsonData.overseaFirstGift
        if isSet(self.overseaFirstGift,"nextReceiveTime") then
            self.overseaFirstGift.nextReceiveTime = self.overseaFirstGift.nextReceiveTime + os.time()
        end
    end

    if isSet(jsonData, "overseaNewFirstGift") then
        self.overseaNewFirstGift = jsonData.overseaNewFirstGift
        if isSet(self.overseaNewFirstGift,"nextReceiveTime") then
            self.overseaNewFirstGift.nextReceiveTime = self.overseaNewFirstGift.nextReceiveTime + os.time()
        end
    end

    if isSet(jsonData, "overseaSpecialGift") then
        self.overseaSpecialGift = jsonData.overseaSpecialGift
    end

    if isSet(jsonData, "payCumulative") then
        self.payCumulative = checkNumber(jsonData.payCumulative)
    end

    -- if isSet(jsonData, "cardSkins") then
    --     local skins = {}
    --     for i, v in ipairs(jsonData.cardSkins) do
    --         skins[tostring(v)] = v
    --     end
    --     self.cardSkins = skins
    -- else
    --     self.cardSkins = {}
    -- end
    if isSet(jsonData, "dailyRefreshTime") then
        self.dailyRefreshTime = checkNumber(jsonData.dailyRefreshTime) + 10--加10秒的延时来做容错
        AppService:GetInstance():SetDailyRefreshTime(self.dailyRefreshTime)
    end
    if isSet(jsonData, "randomTaskStartTime") then
        self.randomTaskStartTime = checkNumber(jsonData.randomTaskStartTime)
        AppService:GetInstance():SetWeekGachaponTime(self.randomTaskStartTime)
    end
    self.unlockGenes = {} --- 解锁的基因ID
    if isSet(jsonData, "unlockGenes") then
        for i, geneId in pairs(jsonData.unlockGenes) do
            self.unlockGenes[tostring(geneId)] = geneId
        end
    end

    if checkInt(self.regressTimeLeft) > 0 then
        self.regressTimeLeft = self.regressTimeLeft + os.time()
    end

    if isSet(jsonData, "album") then
        for albumId, isOwn in pairs(jsonData.album) do
            if checkInt(albumId) > 0 then
                self.ownedAlbumDt[checkInt(albumId)] = checkInt(isOwn)
                if checkInt(isOwn) == 1 then
                    self.selectedAlbumMap[checkInt(albumId)] = true
                end
            end
        end
    end

    if isSet(jsonData, "panel") then
        self.playerPanel = checkInt(jsonData.panel)
        if self.playerPanel <= 0 then
            self.playerPanel = CfUtils.GetCfVo(AutoIds.IdSetting950, "PersonalInfoVo", Constants.PersonalInfoVoId.DefaultThemeId).num
        end
    else
        self.playerPanel = CfUtils.GetCfVo(AutoIds.IdSetting950, "PersonalInfoVo", Constants.PersonalInfoVoId.DefaultThemeId).num
    end
    if checkNumber(self.nextHpSeconds) < 0 then
        self.nextHpSeconds = 0
    end
    if isSet(jsonData, "entryWelfareInfo") then
        self.entryWelfareInfo = checkTable(jsonData.entryWelfareInfo)
    end

    if isSet(jsonData, "dailySignIn") then
        self.dailySignIn = checkTable(jsonData.dailySignIn)
    end

    if isSet(jsonData, "cardStarGifts") then
        self.cardStarGifts = checkTable(jsonData.cardStarGifts)
    end

    if isSet(jsonData, "shareInfo") then
        self.shareInfo = checkTable(jsonData.shareInfo)
    end

    if isSet(jsonData, "notificationConf") then
        self.notificationConf = checkTable(jsonData.notificationConf)
    end

    if isSet(jsonData, "pushSettings") then
        self.pushSettings = checkTable(jsonData.pushSettings)
    end

    if isSet(jsonData, "cardSkinDeepTimes") then
        self.cardSkinDeepTimes = checkTable(jsonData.cardSkinDeepTimes)
    end

    if isSet(jsonData, "chatChannelsStatus") then
        self.chatChannelsStatus = checkTable(jsonData.chatChannelsStatus)
    end
    if isSet(jsonData, "consumeCopyActivity") then
        self.consumeCopyActivity = checkTable(jsonData.consumeCopyActivity)
    end
    if isSet(jsonData, "passCardScheduleId") then
        self.passScheduleId = checkInt(jsonData.passCardScheduleId)
    end
    if isSet(jsonData, "nightmarePassCardScheduleId") then
        self.nightmarePassCardScheduleId = checkInt(jsonData.nightmarePassCardScheduleId)
    end
    if isSet(jsonData, "onlineTaskInfo") then
        self.onlineTaskInfo = checkTable(jsonData.onlineTaskInfo)
    end
    if isSet(jsonData, "equipmentDiySuits") then
        self.equipmentDiySuits = checkTable(jsonData.equipmentDiySuits)
    end
    if isSet(jsonData, "changeSexTtl") then
        self.changeSexLastClientTime = checkNumber(jsonData.changeSexTtl) + os.time()
    end
    if isSet(jsonData, "accountUpgradeRewards") then
        self.accountUpgradeRewards = checkTable(jsonData.accountUpgradeRewards)
    end

    if isSet(jsonData, "lightDarkCoin") then
        self.lightDarkCoin = checkInt(jsonData.lightDarkCoin)
    end
    if isSet(jsonData, "stardustCoin") then
        self.stardustCoin = checkInt(jsonData.stardustCoin)
    end
    if isSet(jsonData, "isVeteran") then
        self.isVeteran = checkInt(jsonData.isVeteran)
    end
    if isSet(jsonData, "showVip") then
        self.showVip = checkInt(jsonData.showVip)
    end
    if isSet(jsonData, "hasDrawVip") then
        self.hasDrawVip = checkInt(jsonData.hasDrawVip)
    end
    
    if isSet(jsonData, "rookieVersion") then
        self.rookieVersion = jsonData.rookieVersion
        local curTime = GameUtils.GetServerTime() or os.time()
        for i, v in pairs(self.rookieVersion) do
            if v > 0 then
                if checkNumber(i) == Constants.BeginnerActivityType.Beginner then
                    self.rookieOpened = v
                end
                self.rookieVersion[tostring(i)] = self.rookieVersion[tostring(i)] + curTime
            end
        end
    end

    if isSet(jsonData, "playerCreateTime") then
        if string.len(jsonData.playerCreateTime) > 0 then
            local timeDetails = string.split(jsonData.playerCreateTime ,"-" )
            if #timeDetails >= 3 then
                local createTime  =  os.time({year = timeDetails[1], month = timeDetails[2], day = timeDetails[3], hour = 0 ,min = 0 ,sec = 0})
                local currentTime =  os.time()
                local day = math.ceil ((currentTime - createTime)/ 86400)
                if day >=1 and day <=7 then
                    xRecord.af_internal("af_retention_day" .. day)
                end
                -- self.playerCreateTime = createTime
            end
        end
    end
    if isSet(jsonData, "paidCheckin") and table.count(jsonData.paidCheckin) > 0 then
        self:UpdatePaidCheckin(jsonData.paidCheckin)
    end
    print('---->>', self.chatHost)
    
    if isSet(jsonData,"nightmareInfo") then
        self.nightmareInfo = checkTable(jsonData.nightmareInfo)
    end

    if isSet(jsonData , "greenBundleId") then
        if checkInt(self.level) <= 35  then
            if jsonData.greenBundleId and table.count(jsonData.greenBundleId) > 0 then
                local kTool = CS.Engine.Lib.KTool
                if kTool.UNITY_ANDROID() then
                    local Application = CS.UnityEngine.Application
                    local identifier = Application.identifier    
                    for k, v in pairs(jsonData.greenBundleId) do
                        if v == identifier then
                            IS_HARMONIOUS = true
                            break
                        end
                    end
                end
            end
        end
    end
end

---IsHavePrivilegeCardById
---是否拥有当前Id的特权卡
---@param cardId number 特权卡的配表Id
function PlayerDojo:IsHavePrivilegeCardById(cardId)
    local isHave = false
    if not isNull(self.overseaPrivilegeCard) and self.overseaPrivilegeCard[tostring(cardId)] then
        local data = self.overseaPrivilegeCard[tostring(cardId)]
        if isSet(data,"roundLeftDay") and isSet(data,"leftSeconds") then
            local leftSeconds = data.leftSeconds
            local endTimeTick = data.endTime
            local curTimeTick = os.time()
            if leftSeconds > 0 and endTimeTick > curTimeTick then
                isHave = true
            end
        end
    end
    return isHave
end

function PlayerDojo:PlayerId(playerId)
    if not isNull(playerId) then
        self.playerId = playerId
        HttpModule.RequestBodyMeta.PlayerId = checkString(playerId)
        xRecord.setUserPlayer({ playerId = tostring(playerId) })
    end
    return self.playerId
end

function PlayerDojo:GuideId(guideId)
    if guideId then
        self.guideId = guideId
    end
    return self.guideId
end
---GetPrivilegeCardInfoById
---@param cardId number 特权卡的配表Id
---有返回值的话 要判定里面的endTime和当前时间戳比较
function PlayerDojo:GetPrivilegeCardInfoById(cardId)
    if self.overseaPrivilegeCard and self.overseaPrivilegeCard[tostring(cardId)] then
        return self.overseaPrivilegeCard[tostring(cardId)]
    end
    return nil
end

function PlayerDojo:AddSpecialGuideId(guideId)
    if guideId == nil then
        return
    end
    self.specialGuide = self.specialGuide or {}
    table.insert(self.specialGuide, guideId)
end

