function PlayerDojo:CheckIsRegressEnd(isShowTips)
    local isEnd = checkInt(self.regressTimeLeft) - os.time() <= 0
    if isEnd and checkBool(isShowTips) then
        GameUtils.Toast(localize("回归活动已结束"))
    end
    return isEnd
end

function PlayerDojo:UpdateSelectedAlbumMap(map)
    self.selectedAlbumMap = checkTable(map)
end

function PlayerDojo:GetSelectedAlbumList()
    return table.keys(self:GetSelectedAlbumMap())
end
