    return checkTable(self.selectedAlbumMap)
end

function PlayerDojo:CheckAlbumIsSelected(albumId)
    return checkBool(self.selectedAlbumMap[checkInt(albumId)])
end

function PlayerDojo:CheckAlbumIsUnlocked(albumId)
    return self.ownedAlbumDt[checkInt(albumId)] ~= nil
end
function PlayerDojo:GetOwnedAlbumNum()
    return table.count(self.ownedAlbumDt)
end

function PlayerDojo:UpdateHistoryTeamsPower(power)
    power = checkNumber(power)
    if power >= checkNumber(self.overseaMaxTeamCombatVal) then
        self.overseaMaxTeamCombatVal = checkNumber(power)
    end
