function PlayerDojo:RegGlobalTalentPrivilegeCard()
     ---@type GlobalTalentMgr
     local instance = GlobalTalentMgr:GetInstance()
     for privilegeCardId, data in pairs(self.overseaPrivilegeCard) do
         local leftSeconds = checkInt(data.leftSeconds)
         local endTimeTick = checkInt(data.endTime)
         local curTimeTick = os.time()
         if leftSeconds > 0 and endTimeTick > curTimeTick then
            local addNum = GameUtils.GetPrivilegeCardAddNumByName(privilegeCardId, "takeOutMoodOff")
            instance:AddActivityTalentData(Constants.GlobalTalentEffectId.Id_13, Constants.GlobalTalentSource.PrivilegeCard, Constants.GlobalTalentAddType.Percent, -1 * addNum, {talentId = privilegeCardId}, endTimeTick)
         end
     end
end

--- 获取 客户端时区
---@return integer
function PlayerDojo:GetClientTimezone()
    local nowTime  = os.time(os.date("*t"))
    local pureTime = os.time(os.date("!*t", nowTime))
    if os.date("*t", os.time()).isdst then
        nowTime = nowTime + 3600
    end
    return os.difftime(nowTime, pureTime)
end


--- 转换 字符串时间 为UTC时间
---@param timestamp string @ 服务器时间戳（有时区），例：2017-12-11 12:42:26 或者 2017-12-11
---@return integer
function PlayerDojo:ServerTimestampToSecond(timestamp)
    local tf = string.gsub(tostring(timestamp or ''), '[- :]', '|')
    local tl = string.split(tf, '|')
    local tt = {
        year  = math.max(1970, checkInt(tl[1])),
        month = math.max(1, checkInt(tl[2])),
        day   = math.max(1, checkInt(tl[3])),
        hour  = checkInt(tl[4]),
        min   = checkInt(tl[5]),
        sec   = checkInt(tl[6]) + self:GetClientTimezone()  -- os.time 是计算 目标时间 和 本地时区的差值，会自带扣除，所以再加上本地时区，就是一个无损转换。
    }
    return os.time(tt)
end


--- 转换 字符串服务器时间 本地化后的 时间格式（服务器时间戳 - 服务器时区 = 纯净时间，再 + 客户端时区 = 当前时间）
---@param timestamp string @ 服务器时间戳
---@param timeFormat string @ 格式化格式
---@return string
function PlayerDojo:l10nTimeData(timestamp, timeFormat)
    local format = tostring(timeFormat or '!%Y-%m-%d %H:%M:%S')
    return os.date(format, self:ServerTimestampToSecond(timestamp) - self:GetServerTimezone() + self:GetClientTimezone())
end

