-- 更新永久付费签到数据
function PlayerDojo:UpdatePaidCheckin(paidCheckin)
    self.paidCheckin = {}
    if type(paidCheckin) == "table" then
        if isSet(paidCheckin , "buyTime") then
            self.paidCheckin.buyTime = os.time() + checkInt(paidCheckin.buyTime)
        end
        if isSet(paidCheckin , "checkinTime") then
            self.paidCheckin.checkinTime = os.time() + checkInt(paidCheckin.checkinTime)
        end
        if isSet(paidCheckin , "hasBuy") then
            self.paidCheckin.hasBuy = checkInt(paidCheckin.hasBuy)
        else 
            self.paidCheckin.hasBuy = checkInt(self.paidCheckin.hasBuy)
        end
    end
end
