---是否开启回响挑战活动
function PlayerDojo:IsOpenActionDark()
    ---@type ChaoticRecallUtils
    local ChaoticRecallUtils = import("Game.UI.FightReady.ChaoticRecall.ChaoticRecallUtils")
    if isSet(self.nightmareInfo,"groups") then
        for i, v in pairs(self.nightmareInfo.groups) do
            local vo = ChaoticRecallUtils.GetChaoticRecallTagVo(v)
            if vo.groupType == 1 then
                return true
            end
        end
    end
    return false
end

function PlayerDojo:IsOpenBeginnerActivity(type)
    local curTime = GameUtils.GetServerTime() or os.time()
    local time = self.rookieVersion[tostring(type)] - curTime
    return checkNumber(time) > 0
end

